(6426804, 953377, 30214, '<td valign="top">very interesting. How I wish it was not a minimum challenge, you could easily make him stand out more against the background</td>', 'very interesting. How I wish it was not a minimum challenge, you could easily make him stand out more against the background', '2011-05-28 15:33:58.000000', NULL, 1),
(6426806, 953648, 30214, '<td valign="top">parallel existences... good work!</td>', 'parallel existences... good work!', '2011-05-28 15:34:38.000000', NULL, 1),
(6426807, 953492, 30214, '<td valign="top">I hope it wins. my favorite in the challenge. lucky you to live in such a street-photogenic place :)</td>', 'I hope it wins. my favorite in the challenge. lucky you to live in such a street-photogenic place :)', '2011-05-28 15:34:42.000000', NULL, 1),
(6426809, 952766, 30214, '<td valign="top">I don''t sense searching, but a nice peaceful scene. Not very HCB-like though, IMO.</td>', 'I don''t sense searching, but a nice peaceful scene. Not very HCB-like though, IMO.', '2011-05-28 15:35:38.000000', NULL, 1),
(6426810, 952740, 30214, '<td valign="top">are you saying this is a candid shot? :) Nice BW.</td>', 'are you saying this is a candid shot? :) Nice BW.', '2011-05-28 15:37:09.000000', NULL, 1),
(6426811, 953173, 30214, '<td valign="top">I like the BW (especially for a minimal ruleset), not sure I am getting the composition.</td>', 'I like the BW (especially for a minimal ruleset), not sure I am getting the composition.', '2011-05-28 15:38:14.000000', NULL, 1),
(6426813, 953657, 30214, '<td valign="top">I thought it was "men only", but then I saw two or three women. Interesting location!</td>', 'I thought it was "men only", but then I saw two or three women. Interesting location!', '2011-05-28 15:39:50.000000', NULL, 1),
