(6427073, 953590, 127021, '<td valign="top">I think this really captures the essence of the challenge - excellent geometry, the moment is right and i like how the woman''s underexposed a bit.  Great photo</td>', 'I think this really captures the essence of the challenge - excellent geometry, the moment is right and i like how the woman''s underexposed a bit.  Great photo', '2011-05-29 05:45:40.000000', NULL, 1),
(6427076, 953055, 127021, '<td valign="top">Excellent use of shutter speed, prominent subject, nice composition.  Nice job.</td>', 'Excellent use of shutter speed, prominent subject, nice composition.  Nice job.', '2011-05-29 05:49:42.000000', NULL, 1),
(6427077, 953353, 127021, '<td valign="top">I didn''t like this photo the first time i saw it, but the second time it struck me and i rated it one of the highest in the competition.  Good use of geometry and rule of thirds...</td>', 'I didn''t like this photo the first time i saw it, but the second time it struck me and i rated it one of the highest in the competition.  Good use of geometry and rule of thirds...', '2011-05-29 05:50:57.000000', NULL, 1),
(6427078, 953402, 127021, '<td valign="top">excellent use of the arc and pathway, i feel like it''s 1/2 second off the moment... maybe that lady in the foreground was about to do something marvelous??? anyway very nice photo.</td>', 'excellent use of the arc and pathway, i feel like it''s 1/2 second off the moment... maybe that lady in the foreground was about to do something marvelous??? anyway very nice photo.', '2011-05-29 05:52:15.000000', NULL, 1),
