(6427384, 953440, 58634, '<td valign="top">I can only wonder what was going on in this iamge.. The horizon is slightly tilted, though.</td>', 'I can only wonder what was going on in this iamge.. The horizon is slightly tilted, though.', '2011-05-29 17:32:52.000000', NULL, 1),
(6427385, 953005, 58634, '<td valign="top">Great title, it fits  the image well. I wish for a slightly tighter crop but I think this works well, too.</td>', 'Great title, it fits  the image well. I wish for a slightly tighter crop but I think this works well, too.', '2011-05-29 17:33:25.000000', NULL, 1),
