(6427389, 953326, 58634, '<td valign="top">This is a total sidenote, but I hate when I see a chef smoking!</td>', 'This is a total sidenote, but I hate when I see a chef smoking!', '2011-05-29 17:35:52.000000', NULL, 1),
(6427395, 953695, 58634, '<td valign="top">Great image and composition. A bit washed out but it''s understandable under challenge entry rules.</td>', 'Great image and composition. A bit washed out but it''s understandable under challenge entry rules.', '2011-05-29 17:39:28.000000', NULL, 1),
(6427397, 953085, 58634, '<td valign="top">I find it OOF, and extremely washed out.</td>', 'I find it OOF, and extremely washed out.', '2011-05-29 17:39:48.000000', NULL, 1),
